window.ProgressiveBuildingPreview={"design":{"format":"progressive-sentence-design-draft","version":1,"status":"draft","courseId":"expression-progressive-needs-pilot-v1","lessonId":"PB001","title":"从“我需要水”到说明需要什么","stageProposal":"S1","audience":"中文母语成人零基础；允许从短句开始，不要求先学音标","goal":"理解并使用 I need…，能添加少量信息并替换对象，在新情境中组织一句表达需要的话。","notGoals":["证明口语发音达标","教授所有不可数名词规则","把please当成任何请求都合适的万能礼貌词","一次讲完否定、问句、时态"],"vocabulary":[{"en":"I","zh":"我","introducedHere":true},{"en":"need","zh":"需要","introducedHere":true},{"en":"water","zh":"水","introducedHere":true},{"en":"some","zh":"一些（本课不强调精确数量）","introducedHere":true},{"en":"please","zh":"用于请求中的礼貌表达","introducedHere":true},{"en":"food","zh":"食物","introducedHere":true},{"en":"tea","zh":"茶","introducedHere":true,"role":"只先教词义和词音，保留完整句组合给新情境检查"}],"chain":[{"id":"base","text":"I need water.","zh":"我需要水。","change":"建立完整的基础表达","focus":["I need","water"],"explanation":"先把 I need… 理解成“我需要……”。这句已经完整，不必等句子变长才能使用。"},{"id":"quantity","from":"base","text":"I need some water.","zh":"我需要一些水。","change":"加入some，补充不精确的数量意思","focus":["some"],"explanation":"在water前加some，表示“一些水”。原句也正确，不是必须加some。"},{"id":"request","from":"quantity","text":"I need some water, please.","zh":"我需要一些水，麻烦了。","change":"加入please，在当前求助情境中表达礼貌","focus":["please"],"explanation":"别人正在问你需要什么，你说出需要后，可以加please。本课暂不比较其他请求句型，也不把这句说成最委婉的说法。"},{"id":"substitute","from":"request","text":"I need some food, please.","zh":"我需要一些食物，麻烦了。","change":"只把water替换成food，保留其他词块","focus":["food"],"explanation":"需要的东西换了，I need some…和please可以保留。"}],"guidedTasks":[{"id":"G1","after":"base","prompt":"现在不是小梅，是你自己需要水。试着说一句。","help":"可看I need…与water词块。","evidence":"guided-practice-only"},{"id":"G2","after":"quantity","prompt":"在刚才的话中补充“一些”的意思。","help":"保留原句，学习者决定some应放在哪里；完成后播放整句。","evidence":"guided-practice-only"},{"id":"G3","after":"request","prompt":"志愿者正问你需要什么。保留意思，加一个礼貌表达。","help":"可选please；强调其位置，不要求拖动所有单词。","evidence":"guided-practice-only"},{"id":"G4","after":"substitute","prompt":"现在需要的是食物，不是水，只修改需要的东西。","help":"听懂food的意思后替换对象。","evidence":"guided-practice-only"}],"transferTasks":[{"id":"T1","scenario":"休息站工作人员请你说明需要。你现在需要茶，请礼貌说明。","targetObject":"tea","withholdSentence":true,"showTokens":false,"candidateAnswers":["I need some tea, please.","I need tea, please.","Some tea, please.","I'd like some tea, please."],"newCombination":true},{"id":"T2","scenario":"线上求助时，对方问需要什么。你需要一些食物，请自己组织一句话。","targetObject":"food","withholdSentence":true,"showTokens":false,"candidateAnswers":["I need some food.","I need some food, please.","I need food.","I'd like some food."],"newCombination":false}],"evaluationPolicy":{"responseModes":["文字表达","口头尝试（不自动判发音）"],"dimensions":["是否表达了正确需要对象","是否独立用了本课I need结构","是否使用some或please","是否看过提示或范文"],"alternativeResponse":"合理但未用本课结构的表达可完成沟通，不认定本课结构证据；未收录的新表达保留待核对，不自动当成错句。","mastery":"单课流程完成不等于掌握；撤提示任务、换情境及后续复习分别记录。","newWord":"tea已先学习词义与词音，T1检验未示范的句子组合，不把词汇猜测混成结构能力。"},"review":{"intervalDaysProposal":[1,3,7],"task":"从茶/水/食物的新情境提取表达，不复用原题措辞，先不给英文句或词块。"},"approval":{"content":"pending","audio":"not-produced","publication":"not-authorized"}},"audio":{"base":"data:audio/mpeg;base64,","quantity":"data:audio/mpeg;base64,","request":"data:audio/mpeg;base64,","substitute":"data:audio/mpeg;base64,","word-water":"data:audio/mpeg;base64,","word-food":"data:audio/mpeg;base64,","word-tea":"data:audio/mpeg;base64,","transfer-tea":"data:audio/mpeg;base64,","transfer-food":"data:audio/mpeg;base64,"}};
